-- Run once in Supabase SQL Editor. Submissions are private/pending until approved.
create table if not exists public.article_comments(id uuid primary key default gen_random_uuid(),article_slug text not null,user_id uuid not null references auth.users(id) on delete cascade,display_name text not null default 'Community member',body text not null check(char_length(body) between 1 and 3000),status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz not null default now());
create index if not exists article_comments_lookup on public.article_comments(article_slug,status,created_at);
create table if not exists public.community_posts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,display_name text not null default 'Community member',title text not null check(char_length(title) between 1 and 120),body text not null check(char_length(body) between 1 and 5000),image_url text,status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz not null default now());
create index if not exists community_posts_lookup on public.community_posts(status,created_at desc);
alter table public.article_comments enable row level security; alter table public.community_posts enable row level security;
grant select on public.article_comments,public.community_posts to anon,authenticated;
grant insert on public.article_comments,public.community_posts to authenticated;
drop policy if exists "Read approved comments or own" on public.article_comments;
create policy "Read approved comments or own" on public.article_comments for select to anon,authenticated using(status='approved' or user_id=(select auth.uid()));
drop policy if exists "Authenticated users submit pending comments" on public.article_comments;
create policy "Authenticated users submit pending comments" on public.article_comments for insert to authenticated with check(user_id=(select auth.uid()) and status='pending' and char_length(trim(body)) between 1 and 3000 and char_length(trim(article_slug)) between 1 and 200);
drop policy if exists "Read approved posts or own" on public.community_posts;
create policy "Read approved posts or own" on public.community_posts for select to anon,authenticated using(status='approved' or user_id=(select auth.uid()));
drop policy if exists "Authenticated users submit pending posts" on public.community_posts;
create policy "Authenticated users submit pending posts" on public.community_posts for insert to authenticated with check(user_id=(select auth.uid()) and status='pending' and char_length(trim(title)) between 1 and 120 and char_length(trim(body)) between 1 and 5000);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('community-images','community-images',true,5242880,array['image/jpeg','image/png','image/webp','image/gif']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp','image/gif'];
drop policy if exists "View community images" on storage.objects;
create policy "View community images" on storage.objects for select to anon,authenticated using(bucket_id='community-images');
drop policy if exists "Upload own community images" on storage.objects;
create policy "Upload own community images" on storage.objects for insert to authenticated with check(bucket_id='community-images' and (storage.foldername(name))[1]=(select auth.uid())::text);
